// Resolve2AE V1.0.1
app.beginUndoGroup('Import Resolve Clips');
var comp = app.project.items.addComp('Link_Timeline_batch_1700000000', 1920, 1080, 1, 1.0, 24.0);
comp.openInViewer();
// Clip: ClipMixA
var fileItem = null;
for (var k=1; k<=app.project.items.length; k++) { if (app.project.items[k].file && app.project.items[k].file.fsName == 'C:/media/audio.wav') { fileItem = app.project.items[k]; break; } }
if (!fileItem) { fileItem = app.project.importFile(new ImportOptions(File('C:/media/audio.wav'))); }
if (fileItem.mainSource && fileItem.mainSource.nativeFrameRate) { fileItem.mainSource.conformFrameRate = fileItem.mainSource.nativeFrameRate; }
var layer = comp.layers.add(fileItem);
layer.name = 'ClipMixA';
layer.enabled = false;
layer.audioEnabled = true;
layer.label = 11;
layer.name = '[Audio] ' + layer.name;
layer.startTime = 0.0 - 0.0;
layer.inPoint = 0.0;
layer.outPoint = 1.0;
// Clip: ClipMixV
var fileItem = null;
for (var k=1; k<=app.project.items.length; k++) { if (app.project.items[k].file && app.project.items[k].file.fsName == 'C:/media/clip.mov') { fileItem = app.project.items[k]; break; } }
if (!fileItem) { fileItem = app.project.importFile(new ImportOptions(File('C:/media/clip.mov'))); }
if (fileItem.mainSource && fileItem.mainSource.nativeFrameRate) { fileItem.mainSource.conformFrameRate = fileItem.mainSource.nativeFrameRate; }
var layer = comp.layers.add(fileItem);
layer.name = 'ClipMixV';
layer.startTime = 0.0 - 0.0;
layer.inPoint = 0.0;
layer.outPoint = 1.0;
app.endUndoGroup();
var jsxFile = new File($.fileName);
if (jsxFile.exists) jsxFile.remove();
